    imports = {
        "lib": lib,
        "other": {
            "h.go": "package other\nfunc H(a, b int64) int64 { return a }\n"
        },
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, imports),
        files,
        target_arch="amd64",
    )
