def test_interface_dispatch_element_receiver_inner_index_order(
    go_types_helper,
):
    # `s.A[Set(&v,x)].B[Get(v)].C[0].M(0)` — Go evaluates `Set`
    # before `Get`, so `Get`'s argument reads `v`'s post-`Set`
    # deps and `x` reaches the result.
    declarations = (
        "type I interface{ M(int64) int64 }\n"
        "type E struct{ F []I }\n"
        "type M0 struct{ B []E }\n"
        "type S struct{ A []M0 }\n"
        "func Set(v *int64, x int64) int64 { *v = x; return 0 }\n"
        "func Get(v int64) int64 { return v }\n"
        "func F(s *S, x int64) int64 {\n"
        "\tvar v int64\n"
        "\treturn s.A[Set(&v, x)].B[Get(v)].F[0].M(0)\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert 1 in result.return_dependencies


def test_interface_dispatch_nested_element_receivers_stay_closed(
    go_types_helper,
):
    # `p.A[i][j].M(x)` — the nested-collection element read itself
    # is unmodelled, so the dispatch stays closed with it.
    declarations = (
        "type I interface{ M(int64) int64 }\n"
        "type S struct{ A [][]I }\n"
        "func F(p *S, i int64, j int64, x int64) int64 { "
        "return p.A[i][j].M(x) }\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert not result.available
    assert any(
        gap.reason == "unresolved_or_opaque_call" for gap in result.gaps
    )


@pytest.mark.parametrize(
    "declarations",
    [
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(p *S, e I) { p.A[0] = e }\n"
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(p *S, i int64, e I) { p.A[i] = e }\n"
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(o S, e I) { o.A[0] = e }\n"
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(p *S, e I) { q := p; q.A[0] = e }\n"
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(pp **S, e I) { (*pp).A[0] = e }\n"
        ),
    ],
)
def test_interface_element_store_through_collection_field(
    go_types_helper, declarations
):
    # `p.A[i] = e` — storing an interface value into a `[]I` field
    # element writes caller-visible element memory the dep model
    # cannot track, so the function reports `unknown` effects like
    # every other element store.
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert result.effects == "unknown"


@pytest.mark.parametrize(
    "declarations, expected",
    [
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func callee(p *S, e I) { p.A[0] = e }\n"
            "func F(p *S, e I) int64 { callee(p, e); "
            "return p.A[0].M() }\n",
            frozenset({0, 1}),
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func callee(p *S, e I) { p.A[0] = e }\n"
            "func F(p *S, e I) int64 { callee(p, e); "
            "v := p.A[0]; return v.M() }\n",
            frozenset({0, 1}),
        ),
        (
            "type I interface{ M() int64 }\n"
            "type S struct{ A []I }\n"
            "func F(p *S, i int64, e I) int64 {\n"
            "\tp.A[i] = e\n"
            "\treturn p.A[i].M()\n"
            "}\n",
            frozenset({0, 1, 2}),
        ),
    ],
)
def test_interface_element_store_observed_by_dispatch(
    go_types_helper, declarations, expected
):
    # A `[]I` element store folds the stored value's deps into the
    # element slot: a later `p.A[i].M()` on the same field observes
    # them like any other element write.
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert result.return_dependencies == expected
    assert result.effects == "unknown"


