def test_interface_member_read_inside_element(
    go_types_helper,
):
    # `v := p.B[i].J` — reading an interface member inside a
    # struct element binds the member slot's interface deps like
    # `v := p.I`; `v.M()` then observes them, and a store into a
    # sibling element's member reaches the same slot.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type E struct{ J I; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(p *S, e I) int64 {\n"
        "\tp.B[0].J = e\n"
        "\tv := p.B[1].J\n"
        "\treturn v.M()\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})
    assert result.effects == "unknown"
    for body, fn in (
        ("v := (*pp).B[0].J", "func F(pp **S) int64 {\n"),
        ("q := p; v := q.B[0].J", "func F(p *S) int64 {\n"),
    ):
        declarations = (
            "type I interface{ M() int64 }\n"
            "type E struct{ J I; V int64 }\n"
            "type S struct{ B []E }\n"
            + fn
            + f"\t{body}\n"
            + "\treturn v.M()\n"
            + "}\n"
        )
        result = named(*unit(go_types_helper, declarations))
        assert result.available, (body, result.gaps)
        assert result.return_dependencies == frozenset({0})
    # A value-struct root stays closed — the read would copy the
    # header, not reach the element's member.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type E struct{ J I; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(o S) int64 {\n"
        "\tv := o.B[0].J\n"
        "\treturn v.M()\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert not result.available


def test_range_struct_element_unsupported_members(
    go_types_helper,
):
    # `for _, e := range p.B` — a struct element whose type has
    # members the snapshot model does not cover (interface,
    # pointer) still binds the copy plainly like `x := p.B[i]`:
    # scalar member reads carry the element's deps, while writes
    # through pointer members stay closed.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type T struct{ V int64 }\n"
        "type E struct{ J I; W *T; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(p *S) int64 {\n"
        "\tn := int64(0)\n"
        "\tfor _, e := range p.B {\n"
        "\t\tn += e.V\n"
        "\t}\n"
        "\treturn n\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0})
    # The copy's interface member still dispatches: `e.J.M()`
    # folds the element's deps through the interface call.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type T struct{ V int64 }\n"
        "type E struct{ J I; W *T; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(p *S) int64 {\n"
        "\tn := int64(0)\n"
        "\tfor _, e := range p.B {\n"
        "\t\tn += e.J.M()\n"
        "\t}\n"
        "\treturn n\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0})
    # A pointer member's pointee stays closed — the write would
    # reach shared memory the copy's plain binding cannot name.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type T struct{ V int64 }\n"
        "type E struct{ J I; W *T; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(p *S, x int64) int64 {\n"
        "\tfor _, e := range p.B {\n"
        "\t\te.W.V = x\n"
        "\t}\n"
        "\treturn 0\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert not result.available
    # An element that also carries a collection member stays
    # closed entirely — `e.A`'s backing is shared with the
    # element's memory and a plain binding cannot name it.
    declarations = (
        "type I interface{ M() int64 }\n"
        "type E struct{ J I; A []int64; V int64 }\n"
        "type S struct{ B []E }\n"
        "func F(p *S) int64 {\n"
        "\tn := int64(0)\n"
        "\tfor _, e := range p.B {\n"
        "\t\tn += e.V\n"
        "\t}\n"
        "\treturn n\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations))
    assert not result.available


def test_callee_pointee_read_observes_prior_writes(
    go_types_helper,
):
    # `get(p)` after `*p = x` — the callee reads caller-shared
    # pointee memory whose stores broadcast into indirect_writes,
    # so the call's deps fold them in.
    declarations = (
        "func get(p *int64) int64 { return *p }\n"
        "func F(p *int64, x int64) int64 {\n"
        "\t*p = x\n"
        "\treturn get(p)\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})
    # A whole-pointee store is observed the same way.
    declarations = (
        "type S struct{ V int64 }\n"
        "func readV(s *S) int64 { return s.V }\n"
        "func F(p *S, s S) int64 {\n"
        "\t*p = s\n"
        "\treturn readV(p)\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})
    # A pointer-receiver method reads the same shared memory.
    declarations = (
        "type S struct{ V int64 }\n"
        "func (s *S) Get() int64 { return s.V }\n"
        "func F(p *S, s S) int64 {\n"
        "\t*p = s\n"
        "\treturn p.Get()\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})
    # Without a pre-call store nothing extra is folded.
    declarations = (
        "func get(p *int64) int64 { return *p }\n"
        "func F(p *int64) int64 { return get(p) }\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0})
    # A whole-pointee copy (`x := *p`) observes the same stores:
    # `*p = s` and `p.V = x` both reach the bound copy's reads.
    declarations = (
        "type S struct{ V int64 }\n"
        "func F(p *S, s S) int64 {\n"
        "\t*p = s\n"
        "\tx := *p\n"
        "\treturn x.V\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})
    # A bound method value freezes the same receiver view:
    # `f := p.Get` after `*p = s` folds the broadcast store.
    declarations = (
        "type S struct{ V int64 }\n"
        "func (s *S) Get() int64 { return s.V }\n"
        "func F(p *S, s S) int64 {\n"
        "\t*p = s\n"
        "\tf := p.Get\n"
        "\treturn f()\n"
        "}\n"
    )
    result = named(*unit(go_types_helper, declarations), "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})


def test_imported_pointer_receiver_observes_prior_pointee_write(
    go_types_helper,
):
    # `p.PF()` on `*lib.S` after `*p = s` — the imported callee
    # reads caller-shared pointee memory whose stores broadcast
    # into `indirect_writes`, so `s` joins the receiver deps.
    files = {
        "a.go": "package p\nimport \"lib\"\n"
        "func F(p *lib.S, s lib.S) int64 {\n"
        "\t*p = s\n"
        "\treturn p.PF()\n"
        "}\n"
    }
    snapshot = _method_snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})


