def test_package_container_field_type_pins_flag_stale_dependents(
    go_types_helper,
):
    type_change_cases = (
        (
            "type Values []int64\n"
            "type Sz struct{ A Values }\n",
            "type Values []int64\n"
            "type Padding int64\n"
            "type Sz struct{ A Values }\n",
            "Sz",
        ),
        (
            "type Sz struct{ A Values }\n"
            "type Values []int64\n",
            "type Sz struct{ A Values }\n"
            "type Padding int64\n"
            "type Values []int64\n",
            "Values",
        ),
    )
    for old_types, new_types, changed_type in type_change_cases:
        files = {
            "a.go": "package p\n"
            + old_types
            + "var GS Sz\n"
            + "func F(i int64) int64 { return GS.A[i] }\n"
        }
        snapshot = _snapshot_for(go_types_helper, files)
        summaries = ip.summarize_go_package(files, snapshot)
        result = named_package(files, snapshot, summaries, "F")
        assert result.available
        changed_id = next(
            binding.id
            for binding in snapshot.bindings
            if binding.name == changed_type and binding.kind == "type"
        )
        assert changed_id in result.pinned
        f_id = next(
            function.binding_id
            for function in snapshot.functions
            if snapshot.binding(function.binding_id).name == "F"
        )
        new_files = {
            "a.go": "package p\n"
            + new_types
            + "var GS Sz\n"
            + "func F(i int64) int64 { return GS.A[i] }\n"
        }
        new_snapshot = _snapshot_for(go_types_helper, new_files)
        new_known = {binding.id for binding in new_snapshot.bindings}
        assert changed_id not in new_known
        assert summaries.stale_dependents(new_known) == frozenset({f_id})


def test_local_composite_write_is_not_a_package_write(
    go_types_helper,
):
    # `st.V = x` on a function-local composite still takes the local
    # accumulate path — the package-var gate never admits it, so no
    # external mutation records (`effects` stays clean).
    files = {
        "a.go": "package p\ntype P struct{ V int64 }\n"
        "func F(x int64) int64 { st := P{}; st.V = x; return st.V }\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "none_in_supported_fragment"
    assert not result.calls


def test_local_struct_promoted_read_through_pointer_stays_closed(
    go_types_helper,
):
    # `st.V` where `V` promotes through embedded `*Q` reads caller
    # memory the conflated dep set cannot represent — a dep-free
    # answer would report `effects` dishonestly, so it stays closed
    # like the write side.
    files = {
        "a.go": "package p\n"
        "type Q struct{ V int64 }\ntype P struct{ *Q }\n"
        "func F(q *Q) int64 { st := P{Q: q}; return st.V }\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert not result.available


