def test_bound_closure_call_inside_literal_opaque_effect(
    go_types_helper,
):
    # A call inside the literal defers an effect the sequencing
    # model cannot place — the call admits as an opaque effectful
    # callee: the result carries the captures' and arguments'
    # deps and records an imported transfer.
    data = unit(
        go_types_helper,
        "func F(x int64) int64 {\n"
        "\th := func() int64 { return G(x) }\n"
        "\treturn h()\n}\n"
        "func G(a int64) int64 { return a }",
    )
    result = named(*data)
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "unknown"


def test_bound_closure_write_inside_lands_at_call(
    go_types_helper,
):
    # A write inside the literal mutates a captured binding —
    # admitted: the literal sequences AT the call site, so `y = 1`
    # folds into y's dep set when `h()` runs (the constant 1 adds
    # no new dep — y keeps its `y := x` set — but the call records
    # the caller-visible write as an imported effect).
    data = unit(
        go_types_helper,
        "func F(x int64) int64 {\n"
        "\ty := x\n"
        "\th := func() { y = 1 }\n"
        "\th()\n"
        "\treturn y\n}",
    )
    result = named(*data)
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "unknown"


def test_bound_closure_write_inside_carries_value_deps(
    go_types_helper,
):
    # `x = y` inside the literal lands y's deps on x when `h()`
    # runs — `return x` after the call reports {0, 1}.
    data = unit(
        go_types_helper,
        "func F(x int64, y int64) int64 {\n"
        "\th := func() { x = y }\n"
        "\th()\n"
        "\treturn x\n}",
    )
    result = named(*data)
    assert result.available
    assert result.return_dependencies == frozenset({0, 1})


def test_bound_closure_mutating_builtin_writes_carry_deps(
    go_types_helper,
):
    # Container-mutating builtins inside the literal write the
    # operand's captured binding like an element store does —
    # `copy(dst, src)` lands the source set on dst, `delete(m, k)`
    # lands the key's deps on m, and a discarded `append(s, x)`
    # still grows s's backing. Without the operand root in the
    # literal's write set the post-call read reported only the
    # binding's pre-call deps and the mutation was lost.
    for body, expected in (
        (
            "func F(p int64, q int64) int64 {\n"
            "\tsrc := []int64{p}\n"
            "\tdst := []int64{q}\n"
            "\tf := func() { _ = copy(dst, src) }\n"
            "\tf()\n"
            "\treturn dst[0]\n}",
            {0, 1},
        ),
        (
            "func F(p int64, q int64) int64 {\n"
            "\tdst := []int64{q}\n"
            "\tsrc := []int64{p}\n"
            "\tf := func() { _ = copy(dst[:1], src) }\n"
            "\tf()\n"
            "\treturn dst[0]\n}",
            {0, 1},
        ),
        (
            "func F(p int64, q int64) int64 {\n"
            "\tm := map[int]int64{0: q}\n"
            "\tf := func() { delete(m, int(p)) }\n"
            "\tf()\n"
            "\treturn m[0]\n}",
            {0, 1},
        ),
        (
            "func F(p int64, q int64) int64 {\n"
            "\ts := []int64{0}\n"
            "\tf := func() { _ = append(s[:0], p) }\n"
            "\tf()\n"
            "\treturn s[0] + q\n}",
            {0, 1},
        ),
        (
            "func F(p int64, q int64) int64 {\n"
            "\tm := map[int]int64{0: q}\n"
            "\tf := func() { clear(m) }\n"
            "\tf()\n"
            "\t_ = p\n"
            "\treturn m[0]\n}",
            {1},
        ),
        (
            "func F(p int64, q int64) int64 {\n"
            "\tdst := []int64{q}\n"
            "\tsrc := []int64{p}\n"
            "\tf := func() { _ = copy(make([]int64, 1), src) }\n"
            "\tf()\n"
            "\treturn dst[0]\n}",
            {1},
        ),
    ):
        data = unit(go_types_helper, body)
        result = named(*data)
        assert result.available
        assert result.return_dependencies == frozenset(expected)


def test_bound_closure_mutating_builtin_unresolvable_operand_stays_closed(
    go_types_helper,
):
    # The builtin's first operand must resolve to a captured
    # binding root — a call result (`identity` may return its own
    # argument's backing) or an unresolvable `(*p)` could write
    # caller memory that only a gap can report.
    for body in (
        "func id(s []int64) []int64 { return s }\n"
        "func F(p int64, q int64) int64 {\n"
        "\tsrc := []int64{p}\n"
        "\tdst := []int64{q}\n"
        "\tf := func() { _ = copy(id(dst), src) }\n"
        "\tf()\n"
        "\treturn dst[0]\n}",
        "func F(p *[]int64, q int64) int64 {\n"
        "\ts := []int64{q}\n"
        "\tf := func() { _ = copy(*p, s) }\n"
        "\tf()\n"
        "\treturn (*p)[0]\n}",
        "func mk(n int64) []int64 { return []int64{n} }\n"
        "func F(p int64, q int64) int64 {\n"
        "\tf := func() { _ = append(mk(0), p) }\n"
        "\tf()\n"
        "\treturn q\n}",
    ):
        data = unit(go_types_helper, body)
        result = named(*data)
        assert not result.available
        assert any(
            gap.reason == "unsupported_expression"
            for gap in result.gaps
        )


