    data = unit(
        go_types_helper,
        "func F(x int64) int64 {\n"
        "\th := func() int64 { return 0 }\n"
        "\ty := x\n"
        "\th = func() int64 { return y }\n"
        "\treturn h()\n}",
    )
    result = named(*data)
    assert result.available
    assert result.return_dependencies == frozenset({0})


