            "\tp <- c\n"
            "}\n"
            "func F_package(c chan int64) {\n"
            "\tGCC <- c\n"
            "}\n"
            "func F_package_range(c chan int64) {\n"
            "\ts := []chan chan int64{}\n"
            "\tfor _, GCC = range s {}\n"
            "\tGCC <- c\n"
            "}\n"
            "func F_alias(p chan chan int64, c chan int64) {\n"
            "\tq := p\n"
            "\tq <- c\n"
