            "\tq3 := make(chan chan chan int64, 1)\n"
            "\tq2 := make(chan chan int64, 1)\n"
            "\tq3 <- q2\n"
            f"\tlib.G({argument})\n"
            "\tc2 := make(chan int64, 1)\n"
            "\tq2 <- c2\n"
            "\tc2 <- x\n"
            "\treturn <-(<-q2)\n"
            "}\n"
