def test_chan_parameter_boundaries_stay_closed(go_types_helper):
    # Non-scalar elements stay closed. A local chan-chan queue now
    # binds a receive-valued name through its share group.
    # A scalar `chan` result (`Res`) admits — ops on the bound name
    # follow the external queue model — and a select over a `chan`
    # parameter admits: each comm case binds the queue's deps and
    # the alternatives union back, so `v` reads the channel's dep
    # and `x` its own.
    files = {
        "a.go": "package p\n"
        "func Ptr(ch chan *int64) int64 { return 0 }\n"
        "func Res(x int64) chan int64 { return make(chan int64) }\n"
        "func Alias(ch chan int64, x int64) int64 {\n"
        "\tq := make(chan chan int64)\n"
        "\tp := <-q\n"
        "\tp <- x\n"
        "\treturn 0\n}\n"
        "func Sel(ch chan int64, x int64) int64 {\n"
        "\tselect {\n"
        "\tcase v := <-ch:\n"
        "\t\treturn v\n"
        "\tdefault:\n"
        "\t\treturn x\n"
        "\t}\n}\n"
    }
    snapshot = _snapshot_for(go_types_helper, files)
    summaries = ip.summarize_go_package(files, snapshot)
    results = {
        name: named_package(files, snapshot, summaries, name)
        for name in ("Ptr", "Res", "Alias", "Sel")
    }
    assert not results["Ptr"].available
    assert results["Res"].available
    assert results["Alias"].available
    assert results["Alias"].effects == "none_in_supported_fragment"
    assert results["Sel"].available
    assert results["Sel"].return_dependencies == frozenset({0, 1})


def test_package_channel_send_recv_close_admitted(go_types_helper):
    # `GC <- x` sends into a queue living in package state: the
    # transfer records on the var's own identity (imported) and the
    # sent value's deps broadcast into `indirect_writes`, so `<-GC`
    # observes them; `close(GC)` records the same caller-visible
    # effect on the var.
    result = named(
        *unit(
            go_types_helper,
            "var GC chan int64\n"
            "func F(x int64) int64 {\n"
            "\tGC <- x\n"
            "\tclose(GC)\n"
            "\treturn <-GC\n}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})
    assert result.effects == "unknown"
    assert len(result.calls) == 3
    assert all(t.imported for t in result.calls)


