@pytest.mark.parametrize(
    "declarations",
    [
        # `delete(m, k)` on an UNBOUND map — no share group
        # exists, so the builtin stays opaque.
        "func F(m map[int64][]chan int64, x int64) int64 {\n"
        "\tdelete(m, 1)\n"
        "\treturn x\n}\n",
        # `a = nil` drops the backing token — `a[0]` afterwards
        # resolves nothing.
        "func F(x int64) int64 {\n"
        "\ta := []int64{x}\n"
        "\ta = nil\n"
        "\treturn a[0]\n}\n",
        # `b := a[i]` on `[][4]int64` — the inner element is an
        # array, so `a[0]` is a value copy with no shared backing.
        "func F(x int64) int64 {\n"
        "\ta := [][4]int64{{0}}\n"
        "\tb := a[0]\n"
        "\tb[0] = x\n"
        "\treturn a[0][0]\n}\n",
        # `b = a[0]` on `[][4]int64` — the reseat form stays
        # closed for the same value-copy reason.
        "func F(x int64) int64 {\n"
        "\ta := [][4]int64{{0}}\n"
        "\tvar b [4]int64\n"
        "\tb = a[0]\n"
        "\tb[0] = x\n"
        "\treturn a[0][0]\n}\n",
        # `b := a[i][j]` on `[][4][4]int64` — the extracted element
        # is a pure array of scalars (a value copy), so `a[0][0]`
        # has no shared backing to name and stays closed.
        "func F(x int64) int64 {\n"
        "\ta := [][4][4]int64{{{0}}}\n"
        "\tb := a[0][0]\n"
        "\tb[0] = x\n"
        "\treturn a[0][0][0]\n}\n",
        # `a := <-cc` — a container received off a channel has no
        # identity to share; the bind stays closed.
        "func F(cc chan []int64, x int64) int64 {\n"
        "\ta := <-cc\n"
        "\ta[0] = x\n"
        "\treturn a[0]\n}\n",
    ],
)
def test_scalar_container_unsupported_stays_closed(
    go_types_helper, declarations
):
    result = named(*unit(go_types_helper, declarations))
    assert not result.available


def test_scalar_container_nested_index_eval_order(go_types_helper):
    # `s[Set(&v,x)][Get(v)].A.V` — Go evaluates the innermost index
    # first, so `Set`'s write to `v` is visible when `Get(v)` runs.
    # The outermost-first order dropped `x`: `Set` returns a
    # constant, so the only way its argument lands is through
    # `Get(v)` observing `v`'s post-`Set` set.
    result = named(
        *unit(
            go_types_helper,
            "type W struct{ V int64 }\n"
            "type St struct{ A W }\n"
            "func Set(v *int64, x int64) int64 { *v = x; return 0 }\n"
            "func Get(v int64) int64 { return v }\n"
            "func F(x int64) int64 {\n"
            "\tvar v int64\n"
            "\ts := [][]St{{St{A: W{V: 0}}}}\n"
            "\treturn s[Set(&v, x)][Get(v)].A.V\n"
            "}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


def test_scalar_container_alias_field_slot(go_types_helper):
    # `t := s` — the aliases share one backing, so a store through
    # `s`'s field extraction must be visible to `t`'s. The field
    # slot resolves to the canonical (mint-earliest) root name, so
    # either alias can seed it first.
    result = named(
        *unit(
            go_types_helper,
            "type St struct{ F []int64 }\n"
            "func F(x int64) int64 {\n"
            "\ts := []St{{F: make([]int64, 2)}}\n"
            "\tt := s\n"
            "\tb := s[0].F\n"
            "\tb[0] = x\n"
            "\tc := t[0].F\n"
            "\treturn c[0]\n"
            "}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


@pytest.mark.parametrize(
    "declarations",
    [
        # Literal field initialization and extraction share one backing.
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\ts := S{A: a}\n"
        "\tb := s.A\n"
        "\tb[0] = x\n"
        "\treturn a[0]\n}\n",
        # Positional composite elements use the same field slot.
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\ts := S{a}\n"
        "\tb := s.A\n"
        "\tb[0] = x\n"
        "\treturn a[0]\n}\n",
        # `var s = S{...}` links the literal donor too.
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\tvar s = S{A: a}\n"
        "\ta[0] = x\n"
        "\tb := s.A\n"
        "\treturn b[0]\n}\n",
        # Reseating a local struct from a literal links its fields.
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\tvar s S\n"
        "\ts = S{A: a}\n"
        "\ta[0] = x\n"
        "\tb := s.A\n"
        "\treturn b[0]\n}\n",
        # Nested struct literals link the leaf slot under the outer root.
        "type W struct { A []int64 }\n"
        "type S struct { W W }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\ts := S{W: W{A: a}}\n"
        "\ta[0] = x\n"
        "\tb := s.W.A\n"
        "\treturn b[0]\n}\n",
        # Both directions of the reported literal-alias probes.
        "type S struct { A []int64; V int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\ts := S{A: a}\n"
        "\tb := s.A\n"
        "\tb[0] = x\n"
        "\treturn a[0]\n}\n",
        "type S struct { A []int64; V int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta := make([]int64, 1)\n"
        "\ts := S{A: a}\n"
        "\ta[0] = x\n"
        "\tb := s.A\n"
        "\treturn b[0]\n}\n",
    ],
)
def test_struct_literal_collection_fields_share_with_donors(
    go_types_helper, declarations
):
    result = named(*unit(go_types_helper, declarations))
    assert result.available
    assert result.return_dependencies == frozenset({0})


