def test_parallel_struct_collection_assignment_uses_prestate(
    go_types_helper,
):
    def dependencies(source):
        result = named(*unit(go_types_helper, source))
        assert result.available, result.gaps
        return result.return_dependencies

    header = (
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ta2 := []int64{0}\n"
        "\ta3 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := S{A: a2}\n"
    )
    two_way_header = (
        "type S struct { A []int64 }\n"
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ta2 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := S{A: a2}\n"
    )
    assert dependencies(
        header
        + "\tw := S{A: a3}\n"
        "\ts, t, w = t, w, s\n"
        "\tb := w.A\n"
        "\tb[0] = x\n"
        "\treturn a1[0]\n}\n"
    ) == frozenset({0})
    assert dependencies(
        header
        + "\tw := S{A: a3}\n"
        "\ts, t, w = t, w, s\n"
        "\tb := w.A\n"
        "\tb[0] = x\n"
        "\treturn a2[0]\n}\n"
    ) == frozenset()
    assert dependencies(
        two_way_header
        + "\tu := s\n"
        "\t_ = u\n"
        "\ts, t = t, s\n"
        "\tb := t.A\n"
        "\tb[0] = x\n"
        "\treturn a1[0]\n}\n"
    ) == frozenset({0})
    assert dependencies(
        two_way_header
        + "\tu := s\n"
        "\ts, t = t, s\n"
        "\tc := u.A\n"
        "\tc[0] = x\n"
        "\treturn a1[0]\n}\n"
    ) == frozenset({0})

    assert dependencies(
        two_way_header
        + "\ts, t = t, s\n"
        "\tb := t.A\n"
        "\tb[0] = x\n"
        "\treturn a1[0]\n}\n"
    ) == frozenset({0})
    assert dependencies(
        two_way_header
        + "\ts, t = t, s\n"
        "\tb := t.A\n"
        "\tb[0] = x\n"
        "\treturn a2[0]\n}\n"
    ) == frozenset()
    assert dependencies(
        two_way_header
        + "\ts = t\n"
        "\tb := s.A\n"
        "\tb[0] = x\n"
        "\treturn a2[0]\n}\n"
    ) == frozenset({0})

    conditional = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64 }\n"
            "func F(x int64, c bool) int64 {\n"
            "\ta1 := []int64{0}\n"
            "\ta2 := []int64{0}\n"
            "\ts := S{A: a1}\n"
            "\tt := S{A: a2}\n"
            "\tif c { s, t = t, s }\n"
            "\tb := t.A\n"
            "\tb[0] = x\n"
            "\treturn a1[0]\n}\n",
        )
    )
    assert conditional.available
    assert conditional.return_dependencies == frozenset({0})

    assert dependencies(
        header
        + "\ts, t = t, S{A: a3}\n"
        "\tb := s.A\n"
        "\tb[0] = x\n"
        "\treturn a2[0]\n}\n"
    ) == frozenset({0})

    unsupported = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64 }\n"
            "func id(s S) S { return s }\n"
            "func F(x int64) int64 {\n"
            "\ta := []int64{0}\n"
            "\tb := []int64{0}\n"
            "\ts := S{A: a}\n"
            "\tt := S{A: b}\n"
            "\ts, t = t, id(s)\n"
            "\treturn a[0]\n}\n",
        )
    )
    assert not unsupported.available
    assert unsupported.gaps[0].reason == "unsupported_expression"


def test_imported_struct_call_result_shares_argument_backing(
    go_types_helper,
):
    files = {
        "main.go": "package p\n"
        "import \"lib\"\n"
        "func F(x, y int64) int64 {\n"
        "\ta := []int64{x}\n"
        "\ts := lib.Mk(a)\n"
        "\tb := s.A\n"
        "\tb[0] = y\n"
        "\treturn a[0]\n}\n",
    }
    imported = {
        "lib": {
            "lib.go": "package lib\n"
            "type S struct { A []int64; V int64 }\n"
            "func Mk(a []int64) S { return S{A: a} }\n"
        }
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, imported),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    result = named_package(files, snapshot, summaries, "F")
    assert result.available
    assert result.return_dependencies == frozenset({0, 1})

    value_files = {
        "main.go": "package p\n"
        "import \"lib\"\n"
        "func F(x int64) int64 {\n"
        "\tvar s = lib.Mk(x)\n"
        "\tb := s.A\n"
        "\treturn b[0]\n}\n",
    }
    value_import = {
        "lib": {
            "lib.go": "package lib\n"
            "type S struct { A []int64; V int64 }\n"
            "func Mk(x int64) S { return S{A: []int64{x}} }\n"
        }
    }
    value_snapshot = load_go_package_snapshot(
        package_report_imports(
            go_types_helper, value_files, value_import
        ),
        value_files,
        target_arch="amd64",
    )
    value_summaries = ip.summarize_go_package(
        value_files, value_snapshot
    )
    value_result = named_package(
        value_files, value_snapshot, value_summaries, "F"
    )
    assert value_result.available
    assert value_result.return_dependencies == frozenset({0})


def test_struct_field_slot_reseat_preserves_only_surviving_aliases(
    go_types_helper,
):
    alias_reseat = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64; V int64 }\n"
            "func F(x int64) int64 {\n"
            "\ts := S{A: []int64{0}}\n"
            "\tt := s\n"
            "\ts = S{A: []int64{1}}\n"
            "\tb := t.A\n"
            "\tb[0] = x\n"
            "\treturn t.V\n}\n",
        )
    )
    assert alias_reseat.available
    assert alias_reseat.return_dependencies == frozenset({0})

    identifier_reseat = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64; V int64 }\n"
            "func F(x int64) int64 {\n"
            "\ts := S{A: []int64{0}}\n"
            "\tt := s\n"
            "\tu := S{A: []int64{1}}\n"
            "\ts = u\n"
            "\tb := t.A\n"
            "\tb[0] = x\n"
            "\treturn t.V\n}\n",
        )
    )
    assert identifier_reseat.available
    assert identifier_reseat.return_dependencies == frozenset({0})

    detached_donor = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64 }\n"
            "func F(x int64) int64 {\n"
            "\tc := []int64{0}\n"
            "\ts := S{A: []int64{1}}\n"
            "\tt := s\n"
            "\ts = S{A: c}\n"
            "\tb := t.A\n"
            "\tb[0] = x\n"
            "\treturn c[0]\n}\n",
        )
    )
    assert detached_donor.available
    assert 0 not in detached_donor.return_dependencies

    retained_donor = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64 }\n"
            "func F(x int64) int64 {\n"
            "\tc := []int64{0}\n"
            "\ts := S{A: c}\n"
            "\tb := s.A\n"
            "\tb[0] = x\n"
            "\treturn c[0]\n}\n",
        )
    )
    assert retained_donor.available
    assert retained_donor.return_dependencies == frozenset({0})


def test_reseating_shared_struct_field_preserves_copied_headers(
    go_types_helper,
):
    sources = (
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := s\n"
        "\tb := t.A\n"
        "\ts.A = []int64{0}\n"
        "\tc := t.A\n"
        "\tt.A = []int64{0}\n"
        "\tc[0] = x\n"
        "\treturn b[0]\n}\n",
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := s\n"
        "\tb := t.A\n"
        "\ts.A = []int64{0}\n"
        "\tc := t.A\n"
        "\tt = S{A: []int64{0}}\n"
        "\t_ = t\n"
        "\tc[0] = x\n"
        "\treturn b[0]\n}\n",
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := s\n"
        "\tb := t.A\n"
        "\ts.A = []int64{0}\n"
        "\ts = S{A: []int64{0}}\n"
        "\t_ = s\n"
        "\tc := t.A\n"
        "\tc[0] = x\n"
        "\treturn b[0]\n}\n",
        "func F(x int64) int64 {\n"
        "\ta1 := []int64{0}\n"
        "\ts := S{A: a1}\n"
        "\tt := s\n"
        "\tb := t.A\n"
        "\ts.A = []int64{0}\n"
        "\tc := t.A\n"
        "\tt.A = []int64{0}\n"
        "\tb[0] = x\n"
        "\treturn c[0]\n}\n",
    )
    for body in sources:
        result = named(
            *unit(
                go_types_helper,
                "type S struct { A []int64; V int64 }\n" + body,
            )
        )
        assert result.available, result.gaps
        assert result.return_dependencies == frozenset({0})

    strong_update = named(
        *unit(
            go_types_helper,
            "type S struct { A []int64; V int64 }\n"
            "func F(x int64) int64 {\n"
            "\ta1 := []int64{0}\n"
            "\ts := S{A: a1}\n"
            "\ts.A = []int64{0}\n"
            "\tc := s.A\n"
            "\tc[0] = x\n"
            "\treturn a1[0]\n}\n",
        )
    )
    assert strong_update.available, strong_update.gaps
    assert strong_update.return_dependencies == frozenset()


def test_pointer_crossing_struct_field_read_stays_closed(
    go_types_helper,
):
    result = named(
        *unit(
            go_types_helper,
            "type P struct { A []int64 }\n"
            "type Q struct { P *P }\n"
            "func F(x int64) int64 {\n"
            "\tp := &P{}\n"
            "\tq := Q{P: p}\n"
            "\tp.A = []int64{x}\n"
            "\tb := q.P.A\n"
            "\treturn b[0]\n}\n",
        )
    )
    assert not result.available
    assert "non_parameter_reference" in {
        gap.reason for gap in result.gaps
    }


