def test_scalar_container_literal_elem_operand(go_types_helper):
    # `s := []St{{F: v}}` — a field operand embedded in the element
    # literal shares `v`'s backing, so `v[0] = x` must reach the
    # field extraction's reads like a direct `s := []St{v2}` does
    # not (a whole-struct operand copies `v2`'s header, matching the
    # composite model's own conflated deps).
    result = named(
        *unit(
            go_types_helper,
            "type St struct{ F []int64 }\n"
            "func F(x int64) int64 {\n"
            "\tv := make([]int64, 2)\n"
            "\ts := []St{{F: v}}\n"
            "\tv[0] = x\n"
            "\tb := s[0].F\n"
            "\treturn b[0]\n"
            "}\n",
        )
    )
    assert result.available
    assert result.return_dependencies == frozenset({0})


@pytest.mark.parametrize(
    ("declarations", "expected"),
    [
        # `s[i] <- x` / `<-s[i]` — the element queues conflate into
        # the container's share group, so the send lands in every
        # sharer's set and the receive reads the union.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\ts[0] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `c <- x` sends through the element's own name — the group
        # carries it, so `<-s[0]` observes the same send.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\tc <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # The mirror image: `s[0] <- x` lands in the group, so a
        # receive through the element name `<-c` sees it too.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\ts[0] <- x\n"
            "\treturn <-c\n}\n",
            frozenset({0}),
        ),
        # `map[K]chan T` elements ride the same model.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tm := map[int64]chan int64{0: c}\n"
            "\tm[0] <- x\n"
            "\treturn <-m[0]\n}\n",
            frozenset({0}),
        ),
        # `b := s` shares the backing — a send through the copy
        # lands in the group's set like an element store does.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\tb := s\n"
            "\tb[0] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `s[0] = c` hands `c`'s queue into the container — its
        # tokens join the group, so `c <- x` reaches `<-s[0]`.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{make(chan int64, 1)}\n"
            "\ts[0] = c\n"
            "\tc <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # A conditional send still deposits into the group — the
        # receive reports the deps unconditionally like `<-ch`.
        (
            "func F(x int64, f bool) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\tif f {\n"
            "\t\ts[0] <- x\n"
            "\t}\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `s = []chan{c2}` reseats the binding: the new literal's
        # element queue joins the group like the mint-time union.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tc2 := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\ts = []chan int64{c2}\n"
            "\ts[0] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `var s []chan = {c}` binds the same way `s :=` does.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\tvar s []chan int64 = []chan int64{c}\n"
            "\ts[0] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `s[i] <- x` — the non-literal index's deps join the
        # stored value like an element store's do.
        (
            "func F(x int64, i int64) int64 {\n"
            "\tc := make(chan int64, 1)\n"
            "\ts := []chan int64{c}\n"
            "\ts[i] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0, 1}),
        ),
        # Consecutive sends accumulate in the queue — the second
        # send must not evict `x`'s dep from the receive.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c}\n"
            "\ts[0] <- x\n"
            "\ts[0] <- 0\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # `c = make(...)` reseats the name but `s[0]` still holds
        # the OLD queue — its sends survive through a surrogate.
        (
            "func F(x int64) int64 {\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c}\n"
            "\tc <- x\n"
            "\tc = make(chan int64, 1)\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # A CONDITIONAL reseat may not run: the group keeps `c`
        # so `c <- x` still reaches `<-s[0]` on the untaken path.
        (
            "func F(x int64, f bool) int64 {\n"
            "\tc := make(chan int64, 4)\n"
            "\ts := []chan int64{c}\n"
            "\tif f {\n"
            "\t\tc = make(chan int64, 1)\n"
            "\t}\n"
            "\tc <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0}),
        ),
        # A caller-owned queue inside the group (`c` is a param):
        # the element send deposits `x`'s dep beside the queue's
        # own contents and records an external mutation.
        (
            "func F(c chan int64, x int64) int64 {\n"
            "\ts := []chan int64{c}\n"
            "\ts[0] <- x\n"
            "\treturn <-s[0]\n}\n",
            frozenset({0, 1}),
        ),
    ],
)
def test_chan_elem_container_send_receive(
    go_types_helper, declarations, expected
):
    result = named(*unit(go_types_helper, declarations))
    assert result.available
    assert result.return_dependencies == expected


