def test_void_callee_pure_effects_none(go_types_helper):
    source, snapshot, summaries = unit(
        go_types_helper,
        "func s(x int64) { }; "
        "func F(x int64) int64 { return x }",
    )
    s = named(source, snapshot, summaries, "s")
    # An empty void body has no statements — the unsupported_body
    # gate keeps it closed rather than claiming effects none.
    assert not s.available


def test_void_callee_external_chan_write_reaches_through_two_hops(
    go_types_helper,
):
    # `mid(x)` calls `inner` which sends on the shared package chan
    # `GC` — the write folds transitively, so `return <-GC` after
    # the call observes x's deps exactly like a direct `G(x)` send.
    files = {
        "a.go": "package p\n"
        "var GC chan int64\n"
        "func inner(v int64) { GC <- v }\n"
        "func mid(v int64) { inner(v) }\n"
        "func F(x int64) int64 { mid(x); return <-GC }\n"
        "func G(x int64) int64 { inner(x); return <-GC }\n"
        "func H(x int64) int64 { GC <- x; return <-GC }\n"
    }
    source, snapshot, summaries = _method_unit(go_types_helper, files)
    f = named_package(files, snapshot, summaries, "F")
    h = named_package(files, snapshot, summaries, "H")
    assert f.available and h.available
    assert f.return_dependencies == h.return_dependencies


def test_go_statement_admitted(go_types_helper):
    # `go g(x)`: the callee and its arguments evaluate at the
    # statement, the goroutine's result is discarded — the call
    # folds like a plain call whose effects may (or may not)
    # happen.
    source, snapshot, summaries = unit(
        go_types_helper,
        "var q = make(chan int64, 8); "
        "func g(x int64) int64 { q <- x; return x }; "
        "func F(x int64) int64 { go g(x); return <-q }",
    )
    result = named(source, snapshot, summaries)
    assert result.available and result.return_dependencies == frozenset({0})


@pytest.mark.parametrize(
    "declarations",
    [
        pytest.param(
            "func F(x, z int64) int64 { y := z; w := int64(0); "
            "g := func() { w = y }; go g(); y = x; return w }",
            id="captured-read-overwritten-after-go",
        ),
        pytest.param(
            "func F(x, z int64) int64 { w := int64(0); "
            "g := func() { w = x }; go g(); w = z; return w }",
            id="captured-write-overwritten-after-go",
        ),
        pytest.param(
            "func F(x, z int64) int64 { w := int64(0); "
            "g := func(v int64) { w = v }; "
            "go g(x); w = z; return w }",
            id="argument-write-overwritten-after-go",
        ),
        pytest.param(
            "func H(p *int64, v int64) { *p = v }\n"
            "func F(x, z int64) int64 { w := z; "
            "go H(&w, x); w = z; return w }",
            id="pointer-argument-write-overwritten-after-go",
        ),
        pytest.param(
            "func F(x int64) int64 { y := int64(0); w := int64(0); "
            "g := func() { w = y }; "
            "for i := 0; i < 1; i++ { go g(); y = x }; return w }",
            id="loop-store-after-go",
        ),
        pytest.param(
            "func F(x, z int64) int64 { w := int64(0); "
            "g := func() { w = x }; h := func() { w = z }; "
            "defer h(); go g(); return w }",
            id="defer-writes-touched-binding",
        ),
        pytest.param(
            "func F(x, z int64) int64 { "
            "s := []int64{0}; t := s; "
            "g := func() { s[0] = x }; go g(); "
            "t[0] = z; return t[0] }",
            id="aliased-container-store-after-go",
        ),
        pytest.param(
            "func F(x, z int64) int64 { w := z; p := &w; "
            "g := func() { w = x }; go g(); *p = z; return w }",
            id="indirect-store-through-address-taken-local",
        ),
    ],
)
def test_go_later_store_races_stay_closed(
    go_types_helper, declarations
):
    result = named(*unit(go_types_helper, declarations))
    assert not result.available
    assert any(
        gap.reason == "unsupported_statement" for gap in result.gaps
    )


