def test_func_result_imported_admitted(go_types_helper):
    # `f := lib.Mk()` — the producer now records `direct_import` for
    # a func-result callee, so the name binds an opaque func value
    # and `f()` resolves through the func-value path.

    files = {
        "a.go": "package p\nimport \"lib\"\n"
        "func F(x int64) int64 { f := lib.Mk(); return f() }\n"
    }
    lib = {
        "lib": {
            "m.go": "package lib\nfunc Mk() func() int64 { return nil }\n"
        }
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, lib),
        files,
        target_arch="amd64",
    )
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available and result.return_dependencies == frozenset()


def test_func_result_capture_updated_before_return(go_types_helper):
    # `cl` captured `y` when it was const — but `y = x` before
    # `return cl` means the closure observes x: the return must
    # re-resolve captured bindings, not the literal's frozen deps.
    files = {
        "a.go": "package p\n"
        "func mk(x int64) func() int64 {\n"
        "    y := int64(0)\n"
        "    cl := func() int64 { return y }\n"
        "    y = x\n"
        "    return cl\n"
        "}\n"
        "func F(a int64) int64 { f := mk(a); return f() }\n"
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    mk = named_package(files, snapshot, summaries, "mk")
    f = named_package(files, snapshot, summaries, "F")
    assert mk.available and mk.return_dependencies == frozenset({0})
    assert f.available and f.return_dependencies == frozenset({0})


def test_bare_return_named_closure_result_resolves_current_captures(
    go_types_helper,
):
    files = {
        "a.go": (
            "package p\n"
            "type S struct { F func() int64 }\n"
            "func G_lit(x, y int64) (r func() int64) {\n"
            "\tv := y; r = func() int64 { return v }; v = x; return\n"
            "}\n"
            "func F_lit(x, y int64) int64 { return G_lit(x, y)() }\n"
            "func G_litexp(x, y int64) (r func() int64) {\n"
            "\tv := y; r = func() int64 { return v }; v = x; return r\n"
            "}\n"
            "func F_litexp(x, y int64) int64 { return G_litexp(x, y)() }\n"
            "func G_named(x, y int64) (r func() int64) {\n"
            "\tv := y; g := func() int64 { return v }; r = g; v = x; return\n"
            "}\n"
            "func F_named(x, y int64) int64 { return G_named(x, y)() }\n"
            "func G_namedexp(x, y int64) (r func() int64) {\n"
            "\tv := y; g := func() int64 { return v }; r = g; v = x; return r\n"
            "}\n"
            "func F_namedexp(x, y int64) int64 { return G_namedexp(x, y)() }\n"
            "func G_sf(x, y int64) (r func() int64) {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tr = s.F; v = x; return\n"
            "}\n"
            "func F_sf(x, y int64) int64 { return G_sf(x, y)() }\n"
            "func G_sfexp(x, y int64) (r func() int64) {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tr = s.F; v = x; return r\n"
            "}\n"
            "func F_sfexp(x, y int64) int64 { return G_sfexp(x, y)() }\n"
            "func G_multi(x, y int64) (r func() int64, n int64) {\n"
            "\tv := y; r = func() int64 { return v }; v = x; return\n"
            "}\n"
            "func F_multi(x, y int64) int64 {\n"
            "\tf, _ := G_multi(x, y); return f()\n"
            "}\n"
            "func G_multiexp(x, y int64) (r func() int64, n int64) {\n"
            "\tv := y; r = func() int64 { return v }; v = x; return r, n\n"
            "}\n"
            "func F_multiexp(x, y int64) int64 {\n"
            "\tf, _ := G_multiexp(x, y); return f()\n"
            "}\n"
            "func G_coll(x, y int64) (fs []func() int64) {\n"
            "\tv := y; fs = []func() int64{func() int64 { return v }}\n"
            "\tv = x; return\n"
            "}\n"
            "func F_coll(x, y int64) int64 { return G_coll(x, y)[0]() }\n"
            "func G_collexp(x, y int64) (fs []func() int64) {\n"
            "\tv := y; fs = []func() int64{func() int64 { return v }}\n"
            "\tv = x; return fs\n"
            "}\n"
            "func F_collexp(x, y int64) int64 { return G_collexp(x, y)[0]() }\n"
            "func G_wlit(x int64, w *int64) (r func()) {\n"
            "\tr = func() { *w = x }; return\n"
            "}\n"
            "func F_wlit(x int64) int64 {\n"
            "\tw := int64(0); G_wlit(x, &w)(); return w\n"
            "}\n"
            "func G_wlitexp(x int64, w *int64) (r func()) {\n"
            "\tr = func() { *w = x }; return r\n"
            "}\n"
            "func F_wlitexp(x int64) int64 {\n"
            "\tw := int64(0); G_wlitexp(x, &w)(); return w\n"
            "}\n"
        ),
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    expected = {
        "F_lit": frozenset({0}),
        "F_litexp": frozenset({0}),
        "F_named": frozenset({0}),
        "F_namedexp": frozenset({0}),
        "F_sf": frozenset({0, 1}),
        "F_sfexp": frozenset({0, 1}),
        "F_multi": frozenset({0}),
        "F_multiexp": frozenset({0}),
        "F_coll": frozenset({0, 1}),
        "F_collexp": frozenset({0, 1}),
        "F_wlit": frozenset({0}),
        "F_wlitexp": frozenset({0}),
    }
    for function_name, dependencies in expected.items():
        result = named_package(files, snapshot, summaries, function_name)
        assert result.available, (function_name, result.gaps)
        assert result.return_dependencies == dependencies, (
            function_name,
            result.return_dependencies,
        )


def test_closures_handed_to_opaque_callees(go_types_helper):
    files = {
        "a.go": (
            "package p\n"
            "type K interface {\n"
            "\tSet(func() int64); Get() int64; Do(func()); Take(int64)\n"
            "\tHold(func()); Fire(); Put(S); SetAll([]func() int64)\n"
            "\tTakeStruct(struct{ F func() int64 }); TakeAny([]any)\n"
            "}\n"
            "type S struct { F func() int64 }\n"
            "func set(p *int64, v int64) { *p = v }\n"
            "func F_setlit(x, y int64, k K) int64 {\n"
            "\tv := y; k.Set(func() int64 { return v }); v = x\n"
            "\treturn k.Get()\n"
            "}\n"
            "func F_setnamed(x, y int64, k K) int64 {\n"
            "\tv := y; g := func() int64 { return v }; k.Set(g); v = x\n"
            "\treturn k.Get()\n"
            "}\n"
            "func F_setfield(x, y int64, k K) int64 {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tk.Set(s.F); v = x; return k.Get()\n"
            "}\n"
            "func F_putstruct(x, y int64, k K) int64 {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tk.Put(s); v = x; return k.Get()\n"
            "}\n"
            "func F_sliceargument(x1, y1, x2, y2 int64, k K) int64 {\n"
            "\tv1 := y1; v2 := y2\n"
            "\tfs := []func() int64{func() int64 { return v1 }, func() int64 { return v2 }}\n"
            "\tk.SetAll(fs[:]); v1 = x1; v2 = x2; return k.Get()\n"
            "}\n"
            "func F_appendargument(x1, y1, x2, y2 int64, k K) int64 {\n"
            "\tv1 := y1; v2 := y2; g := func() int64 { return v2 }\n"
            "\tfs := []func() int64{func() int64 { return v1 }}\n"
            "\tk.SetAll(append(fs, g)); v1 = x1; v2 = x2; return k.Get()\n"
            "}\n"
            "func F_getafter(x, y int64, k K) int64 {\n"
            "\tv := y; k.Set(func() int64 { return v }); v = x\n"
            "\tr := k.Get(); return r\n"
            "}\n"
            "func F_cbset(x, y int64, set func(func() int64), get func() int64) int64 {\n"
            "\tv := y; set(func() int64 { return v }); v = x\n"
            "\treturn get()\n"
            "}\n"
            "var opaqueHold func(func() int64)\n"
            "var opaqueFire func() int64\n"
            "func F_pkgvar(x, y int64) int64 {\n"
            "\tv := y; opaqueHold(func() int64 { return v }); v = x\n"
            "\treturn opaqueFire()\n"
            "}\n"
            "func F_replayw(x int64, k K) (w int64) {\n"
            "\th := func() { w = x }; k.Hold(h); w = 0; k.Fire()\n"
            "\treturn w\n"
            "}\n"
            "func F_replaylitw(x int64, k K) (w int64) {\n"
            "\tk.Hold(func() { w = x }); w = 0; k.Fire(); return w\n"
            "}\n"
            "func F_pointerwrite(x, y int64, k K) (w int64) {\n"
            "\tv := y; k.Hold(func() { set(&w, v) }); v = x\n"
            "\tk.Fire(); return w\n"
            "}\n"
            "func F_pointerwritenamed(x, y int64, k K) (w int64) {\n"
            "\tv := y; h := func() { set(&w, v) }\n"
            "\tk.Hold(h); v = x; k.Fire(); return w\n"
            "}\n"
            "func F_pointerwritenested(x, y int64, k K) (w int64) {\n"
            "\tv := y; h := func() { set(&w, v) }\n"
            "\tk.Hold(func() { h() }); w = 0; k.Fire(); return w\n"
            "}\n"
            "func F_pointerwritealias(x, y int64, k K) (w int64) {\n"
            "\tv := y; pw := &w\n"
            "\tk.Hold(func() { p := pw; set(p, v) }); k.Fire(); return w\n"
            "}\n"
            "func F_pointerread(y int64, k K) int64 {\n"
            "\tv := y; p := &v; k.Hold(func() { _ = *p + 1 })\n"
            "\tk.Fire(); return v\n"
            "}\n"
            "func F_pointerreadnamed(y int64, k K) int64 {\n"
            "\tv := y; p := &v; h := func() { _ = *p + 1 }\n"
            "\tk.Hold(h); k.Fire(); return v\n"
            "}\n"
            "func F_addressread(y int64, k K) int64 {\n"
            "\tv := y; k.Hold(func() { _ = *(&v) + 1 })\n"
            "\tk.Fire(); return v\n"
            "}\n"
            "func F_pointerreadnoafter(y int64, k K) int64 {\n"
            "\tv := y; p := &v; k.Hold(func() { _ = *p + 1 })\n"
            "\treturn v\n"
            "}\n"
            "func F_replaycap(x, y int64, k K) (w int64) {\n"
            "\tx2 := x; k.Hold(func() { w = x2 }); x2 = y\n"
            "\tk.Fire(); return w\n"
            "}\n"
            "func F_cbreplay(x int64, hold func(func()), fire func()) (w int64) {\n"
            "\thold(func() { w = x }); w = 0; fire(); return w\n"
            "}\n"
            "func fireK(k K) { k.Fire() }\n"
            "func F_localfire(x int64, k K) (w int64) {\n"
            "\tk.Hold(func() { w = x }); w = 0; fireK(k); return w\n"
            "}\n"
            "func F_loopwrite(x int64, k K) (w int64) {\n"
            "\tfor i := 0; i < 2; i++ { k.Hold(func() { w = x }) }\n"
            "\treturn w\n"
            "}\n"
            "func F_deferwrite(x int64, k K) (w int64) {\n"
            "\tdefer k.Fire(); k.Hold(func() { w = x }); return w\n"
            "}\n"
            "func F_dowrite(x int64, k K) (w int64) {\n"
            "\tk.Do(func() { w = x }); return w\n"
            "}\n"
            "func F_scalarfactory(x int64, k K) (w int64) {\n"
            "\tg := func() int64 { w = x; return 1 }\n"
            "\tk.Take(g()); k.Fire(); return w\n"
            "}\n"
            "func F_structfactory(x, y int64, k K) int64 {\n"
            "\tv := y\n"
            "\tg := func() struct{ F func() int64 } {\n"
            "\t\treturn struct{ F func() int64 }{F: func() int64 { return v }}\n"
            "\t}\n"
            "\tk.TakeStruct(g()); v = x; return k.Get()\n"
            "}\n"
            "func F_interfacefactory(x, y int64, k K) int64 {\n"
            "\tv := y\n"
            "\tmk := func() []any { return []any{func() int64 { return v }} }\n"
            "\tk.TakeAny(mk()); v = x; return k.Get()\n"
            "}\n"
            "func F_cbdo(x int64, do func(func())) (w int64) {\n"
            "\tdo(func() { w = x }); return w\n"
            "}\n"
            "func F_noafter(x, y int64, k K) int64 {\n"
            "\tv := y; k.Set(func() int64 { return v }); v = x; return v\n"
            "}\n"
            "func F_setptr(x, y int64, k K) int64 {\n"
            "\tv := y; p := &v; _ = p\n"
            "\tk.Set(func() int64 { return v }); v = x; return k.Get()\n"
            "}\n"
        )
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    unavailable = {
        "F_replayw",
        "F_replaylitw",
        "F_replaycap",
        "F_cbreplay",
        "F_localfire",
        "F_loopwrite",
        "F_deferwrite",
        "F_pointerwrite",
        "F_pointerwritenamed",
        "F_pointerwritenested",
        "F_pointerwritealias",
        "F_pointerread",
        "F_pointerreadnamed",
        "F_addressread",
    }
    for function_name in unavailable:
        result = named_package(files, snapshot, summaries, function_name)
        assert not result.available, (
            function_name,
            result.return_dependencies,
            result.gaps,
        )
        assert any(
            gap.reason == "unsupported_expression" for gap in result.gaps
        ), (function_name, result.gaps)

    expected = {
        "F_setlit": frozenset({0, 1, 2}),
        "F_setnamed": frozenset({0, 1, 2}),
        "F_setfield": frozenset({0, 1, 2}),
        "F_putstruct": frozenset({0, 1, 2}),
        "F_sliceargument": frozenset({0, 1, 2, 3, 4}),
        "F_appendargument": frozenset({0, 1, 2, 3, 4}),
        "F_getafter": frozenset({0, 1, 2}),
        "F_cbset": frozenset({0, 1, 2, 3}),
        "F_pkgvar": frozenset({0, 1}),
        "F_pointerreadnoafter": frozenset({0, 1}),
        "F_dowrite": frozenset({0}),
        "F_scalarfactory": frozenset({0}),
        "F_structfactory": frozenset({0, 1, 2}),
        "F_interfacefactory": frozenset({0, 1, 2}),
        "F_cbdo": frozenset({0}),
        "F_noafter": frozenset({0}),
        "F_setptr": frozenset({0, 1, 2}),
    }
    for function_name, dependencies in expected.items():
        result = named_package(files, snapshot, summaries, function_name)
        assert result.available, (function_name, result.gaps)
        assert result.return_dependencies == dependencies, (
            function_name,
            result.return_dependencies,
        )


def test_parenthesized_rhs_binds_closure_records(go_types_helper):
    files = {
        "a.go": (
            "package p\n"
            "type S struct { F func() int64 }\n"
            "func F_short_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; f := (g)\n"
            "\tv = x; return f()\n"
            "}\n"
            "func F_short_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; f := g\n"
            "\tv = x; return f()\n"
            "}\n"
            "func F_assign_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tvar f func() int64; f = (g); v = x; return f()\n"
            "}\n"
            "func F_assign_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tvar f func() int64; f = g; v = x; return f()\n"
            "}\n"
            "func F_var_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; var f = (g)\n"
            "\tv = x; return f()\n"
            "}\n"
            "func F_var_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; var f = g\n"
            "\tv = x; return f()\n"
            "}\n"
            "func F_slice_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tfs := ([]func() int64{g}); v = x; return fs[0]()\n"
            "}\n"
            "func F_slice_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tfs := []func() int64{g}; v = x; return fs[0]()\n"
            "}\n"
            "func F_assign_slice_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; var fs []func() int64\n"
            "\tfs = ([]func() int64{g}); v = x; return fs[0]()\n"
            "}\n"
            "func F_assign_slice_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; var fs []func() int64\n"
            "\tfs = []func() int64{g}; v = x; return fs[0]()\n"
            "}\n"
            "func F_var_slice_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tvar fs = ([]func() int64{g}); v = x; return fs[0]()\n"
            "}\n"
            "func F_var_slice_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tvar fs = []func() int64{g}; v = x; return fs[0]()\n"
            "}\n"
            "func F_slice_field_paren(x, y int64) int64 {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tfs := ([]func() int64{s.F}); v = x; return fs[0]()\n"
            "}\n"
            "func F_slice_field_plain(x, y int64) int64 {\n"
            "\tv := y; s := S{F: func() int64 { return v }}\n"
            "\tfs := []func() int64{s.F}; v = x; return fs[0]()\n"
            "}\n"
            "func F_map_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tm := (map[int]func() int64{0: g}); v = x; return m[0]()\n"
            "}\n"
            "func F_map_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }\n"
            "\tm := map[int]func() int64{0: g}; v = x; return m[0]()\n"
            "}\n"
            "func F_write_paren(x int64) int64 {\n"
            "\tw := int64(0); h := func() { w = x }; f := (h)\n"
            "\tf(); return w\n"
            "}\n"
            "func F_write_plain(x int64) int64 {\n"
            "\tw := int64(0); h := func() { w = x }; f := h\n"
            "\tf(); return w\n"
            "}\n"
            "func F_nested_paren(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; f := ((g))\n"
            "\tv = x; return f()\n"
            "}\n"
            "func F_nested_plain(x, y int64) int64 {\n"
            "\tv := y; g := func() int64 { return v }; f := g\n"
            "\tv = x; return f()\n"
            "}\n"
        ),
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    expected = {
        "F_short_paren": frozenset({0}),
        "F_short_plain": frozenset({0}),
        "F_assign_paren": frozenset({0}),
        "F_assign_plain": frozenset({0}),
        "F_var_paren": frozenset({0}),
        "F_var_plain": frozenset({0}),
        "F_slice_paren": frozenset({0, 1}),
        "F_slice_plain": frozenset({0, 1}),
        "F_assign_slice_paren": frozenset({0, 1}),
        "F_assign_slice_plain": frozenset({0, 1}),
        "F_var_slice_paren": frozenset({0, 1}),
        "F_var_slice_plain": frozenset({0, 1}),
        "F_slice_field_paren": frozenset({0, 1}),
        "F_slice_field_plain": frozenset({0, 1}),
        "F_map_paren": frozenset({0, 1}),
        "F_map_plain": frozenset({0, 1}),
        "F_write_paren": frozenset({0}),
        "F_write_plain": frozenset({0}),
        "F_nested_paren": frozenset({0}),
        "F_nested_plain": frozenset({0}),
    }
    results = {}
    for function_name, dependencies in expected.items():
        result = named_package(files, snapshot, summaries, function_name)
        assert result.available, (function_name, result.gaps)
        assert result.return_dependencies == dependencies, (
            function_name,
            result.return_dependencies,
        )
        results[function_name] = result.return_dependencies
    for parenthesized, plain in (
        ("F_short_paren", "F_short_plain"),
        ("F_assign_paren", "F_assign_plain"),
        ("F_var_paren", "F_var_plain"),
        ("F_slice_paren", "F_slice_plain"),
        ("F_assign_slice_paren", "F_assign_slice_plain"),
        ("F_var_slice_paren", "F_var_slice_plain"),
        ("F_slice_field_paren", "F_slice_field_plain"),
        ("F_map_paren", "F_map_plain"),
        ("F_write_paren", "F_write_plain"),
        ("F_nested_paren", "F_nested_plain"),
    ):
        assert results[parenthesized] == results[plain]


def test_opaque_func_value_reads_current_escaped_deps(go_types_helper):
    files = {
        "a.go": (
            "package p\n"
            "func mk(v *int64) func() int64 {\n"
            "\treturn func() int64 { return *v }\n"
            "}\n"
            "func mkv(v int64) func() int64 {\n"
            "\treturn func() int64 { return v }\n"
            "}\n"
            "func ap(cb func() int64) int64 { return cb() }\n"
            "func pkgfn() int64 { return 7 }\n"
            "func F_call(x, y int64) int64 {\n"
            "\tv := y; h := mk(&v); v = x; return h()\n"
            "}\n"
            "func G_ret(x, y int64) func() int64 {\n"
            "\tv := y; h := mk(&v); v = x; return h\n"
            "}\n"
            "func F_ret(x, y int64) int64 { return G_ret(x, y)() }\n"
            "func G_named(x, y int64) (r func() int64) {\n"
            "\tv := y; r = mk(&v); v = x; return r\n"
            "}\n"
            "func F_named(x, y int64) int64 {\n"
            "\treturn G_named(x, y)()\n"
            "}\n"
            "func G_bare(x, y int64) (r func() int64) {\n"
            "\tv := y; r = mk(&v); v = x; return\n"
            "}\n"
            "func F_bare(x, y int64) int64 { return G_bare(x, y)() }\n"
            "func F_ap(x, y int64) int64 {\n"
            "\tv := y; h := mk(&v); v = x; return ap(h)\n"
            "}\n"
            "func F_val(x, y int64) int64 {\n"
            "\tv := y; h := mkv(v); v = x; return ap(h)\n"
            "}\n"
            "func F_alias(x int64) int64 {\n"
            "\tw := x; p := &w; _ = p; h := pkgfn; return h()\n"
            "}\n"
            "func F_alias_ap(x int64) int64 {\n"
            "\tw := x; p := &w; _ = p; h := pkgfn; return ap(h)\n"
            "}\n"
        ),
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    expected = {
        "F_call": frozenset({0, 1}),
        "F_ret": frozenset({0, 1}),
        "F_named": frozenset({0, 1}),
        "F_bare": frozenset({0, 1}),
        "F_ap": frozenset({0, 1}),
        "F_val": frozenset({1}),
        "F_alias": frozenset(),
        "F_alias_ap": frozenset(),
    }
    for function_name, dependencies in expected.items():
        result = named_package(files, snapshot, summaries, function_name)
        assert result.available, (function_name, result.gaps)
        assert result.return_dependencies == dependencies, (
            function_name,
            result.return_dependencies,
        )


def test_func_result_captured_chan_send_after_bind(go_types_helper):
    # `f := mk(ch)` — the returned closure may capture `ch`, so the
    # queue escapes: `ch <- x` after the call broadcasts into the
    # shared model and `f()` observes x.
    files = {
        "a.go": "package p\n"
        "func mk(ch chan int64) func() int64 {\n"
        "    return func() int64 { return <-ch }\n"
        "}\n"
        "func F(x int64) int64 {\n"
        "    ch := make(chan int64)\n"
        "    f := mk(ch)\n"
        "    ch <- x\n"
        "    return f()\n"
        "}\n"
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, {}),
        files,
        target_arch="amd64",
    )
    result = named_package(
        files, snapshot, ip.summarize_go_package(files, snapshot), "F"
    )
    assert result.available and result.return_dependencies == frozenset({0})



def test_imported_opaque_call_folds_escaped_callback_bindings(
    go_types_helper,
):
    files = {
        "a.go": (
            "package p\nimport \"lib\"\n"
            "func F(x, y int64) int64 {\n"
            "\tv := y; lib.Set(func() int64 { return v }); v = x\n"
            "\treturn lib.Get()\n"
            "}\n"
        )
    }
    lib = {
        "lib": {
            "lib.go": (
                "package lib\n"
                "var callback func() int64\n"
                "func Set(f func() int64) { callback = f }\n"
                "func Get() int64 { return callback() }\n"
            )
        }
    }
    snapshot = load_go_package_snapshot(
        package_report_imports(go_types_helper, files, lib),
        files,
        target_arch="amd64",
    )
    summaries = ip.summarize_go_package(files, snapshot)
    result = named_package(files, snapshot, summaries, "F")
    assert result.available, result.gaps
    assert result.return_dependencies == frozenset({0, 1})


