        "    c := b\n"
        "    a2 := []func() int64{func() int64 { return 0 }}\n"
        "    if cond {\n"
        "        b = a2\n"
        "    }\n"
        "    d := a2\n"
        "    c[0] = func() int64 { return x }\n"
        "    _ = b\n"
